import type { Locale } from 'date-fns';
import {
  addMonths,
  eachDayOfInterval,
  endOfMonth,
  endOfWeek,
  format,
  isAfter,
  isBefore,
  isSameDay,
  isSameMonth,
  isToday,
  startOfDay,
  startOfMonth,
  startOfWeek,
  subMonths,
} from 'date-fns';
import { enUS } from 'date-fns/locale';
import { ChevronLeft, ChevronRight } from 'lucide-react-native';
import { useState } from 'react';
import { I18nManager, Pressable, View } from 'react-native';

import { cn } from '@/lib/utils';

import { Icon } from './icon';
import { Text } from './text';

export interface CalendarLabels {
  previousMonth: string;
  nextMonth: string;
  today: string;
}

const DEFAULT_LABELS: CalendarLabels = {
  previousMonth: 'Previous month',
  nextMonth: 'Next month',
  today: 'Today',
};

export interface CalendarProps {
  value?: Date;
  onChange?: (date: Date) => void;
  /** Month to show on mount (defaults to `value`, else today). */
  initialMonth?: Date;
  minDate?: Date;
  maxDate?: Date;
  /** date-fns locale for month/weekday names + week start. Pass `useDateFnsLocale()`. */
  locale?: Locale;
  /** Override the first day of the week (0 = Sunday). Defaults to the locale's. */
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  /** Accessibility labels — localize these via your i18n layer. */
  labels?: Partial<CalendarLabels>;
  className?: string;
}

/** Pure-JS month calendar (no native date-picker dependency). Built on date-fns. */
export function Calendar({
  value,
  onChange,
  initialMonth,
  minDate,
  maxDate,
  locale = enUS,
  weekStartsOn,
  labels,
  className,
}: CalendarProps) {
  const [month, setMonth] = useState(() => startOfMonth(initialMonth ?? value ?? new Date()));
  const l = { ...DEFAULT_LABELS, ...labels };
  const weekOptions = { weekStartsOn, locale };

  const gridStart = startOfWeek(startOfMonth(month), weekOptions);
  const gridEnd = endOfWeek(endOfMonth(month), weekOptions);
  const days = eachDayOfInterval({ start: gridStart, end: gridEnd });
  const weekdays = eachDayOfInterval({ start: gridStart, end: endOfWeek(gridStart, weekOptions) });

  const weeks: Date[][] = [];
  for (let i = 0; i < days.length; i += 7) weeks.push(days.slice(i, i + 7));

  function isDisabled(day: Date): boolean {
    if (minDate && isBefore(startOfDay(day), startOfDay(minDate))) return true;
    if (maxDate && isAfter(startOfDay(day), startOfDay(maxDate))) return true;
    return false;
  }

  return (
    <View className={cn('gap-2', className)}>
      <View className="flex-row items-center justify-between">
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={l.previousMonth}
          hitSlop={8}
          onPress={() => setMonth(subMonths(month, 1))}
          className="h-9 w-9 items-center justify-center rounded-full"
        >
          <Icon
            as={I18nManager.isRTL ? ChevronRight : ChevronLeft}
            size={20}
            className="text-foreground"
          />
        </Pressable>
        <Text className="text-sm font-medium">{format(month, 'MMMM yyyy', { locale })}</Text>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={l.nextMonth}
          hitSlop={8}
          onPress={() => setMonth(addMonths(month, 1))}
          className="h-9 w-9 items-center justify-center rounded-full"
        >
          <Icon
            as={I18nManager.isRTL ? ChevronLeft : ChevronRight}
            size={20}
            className="text-foreground"
          />
        </Pressable>
      </View>

      <View className="flex-row">
        {weekdays.map((day) => (
          <View key={day.toISOString()} className="flex-1 items-center py-1">
            <Text className="text-xs text-muted-foreground">
              {format(day, 'EEEEE', { locale })}
            </Text>
          </View>
        ))}
      </View>

      {weeks.map((week, weekIndex) => (
        <View key={weekIndex} className="flex-row">
          {week.map((day) => {
            const selected = value ? isSameDay(day, value) : false;
            const disabled = isDisabled(day);
            const outside = !isSameMonth(day, month);
            const today = isToday(day);
            const fullDate = format(day, 'PPPP', { locale });
            return (
              <Pressable
                key={day.toISOString()}
                accessibilityRole="button"
                accessibilityLabel={today ? `${fullDate}, ${l.today}` : fullDate}
                accessibilityState={{ selected, disabled }}
                disabled={disabled}
                onPress={() => onChange?.(day)}
                className="flex-1 items-center py-1"
              >
                <View
                  className={cn(
                    'h-9 w-9 items-center justify-center rounded-full',
                    selected && 'bg-primary',
                    !selected && today && 'border border-primary',
                  )}
                >
                  <Text
                    className={cn(
                      selected
                        ? 'text-primary-foreground'
                        : outside
                          ? 'text-muted-foreground'
                          : 'text-foreground',
                      disabled && 'opacity-30',
                    )}
                  >
                    {format(day, 'd')}
                  </Text>
                </View>
              </Pressable>
            );
          })}
        </View>
      ))}
    </View>
  );
}
